import json,glob,os,re
runs={'a31151':'4383c6264deaf3410877e957b8f891f1f3da2936','bc19c5':'84fb7ecd4aa0f4a1ab2a71b3fec90e281f407964','d8f5ef':'37a3ebb74a30bacfa2ab2379c86fa408af47a2fd','cadc26':'ceeb3c6c371878d0818744024906d9acd941dc6a','5402cb':'b000c8efdc1973bb7b24cd9430e5f9a612f2bf24'}
def parse(s):
    s=s.strip()
    m=re.search(r'\[罪名\](.*?)(?:<eoa>|$)',s)
    if m: s=m.group(1).strip()
    elif '罪名:' in s: s=s.split('罪名:')[-1]
    s=re.sub(r'<eoa>.*','',s).strip()
    for sep in [';','；',',','，','、']:
        if sep in s: return {p.strip() for p in s.split(sep) if p.strip()}
    return {s} if s else set()
for name,tree in runs.items():
    p=f'/workspace/runs/{tree}/LawBench/conversations'
    stats={'ok_exact':0,'subset':0,'superset':0,'overlap':0,'disjoint':0,'empty':0}
    lens_t=[];lens_p=[]
    for d in sorted(os.listdir(p)):
        if d=='prepare': continue
        for f in sorted(glob.glob(f'{p}/{d}/sample-*.json')):
            t=json.load(open(f))
            if t['status']!='ok': 
                stats['empty']+=1; continue
            pr=parse(t['prediction']); tg=parse(t['target'])
            lens_t.append(len(tg)); lens_p.append(len(pr))
            if pr==tg: stats['ok_exact']+=1
            elif not pr: stats['empty']+=1
            elif pr<tg: stats['subset']+=1
            elif pr>tg: stats['superset']+=1
            elif pr&tg: stats['overlap']+=1
            else: stats['disjoint']+=1
    print(f"{name:8s} {stats}  mean|tgt|={sum(lens_t)/len(lens_t):.2f} mean|pred|={sum(lens_p)/len(lens_p):.2f}")
EOF

