import json,re
tree='4383c6264deaf3410877e957b8f891f1f3da2936'
def txt(m):
    c=m.get('content')
    if isinstance(c,list): return ''.join(x.get('text','') if isinstance(x,dict) else str(x) for x in c)
    return c or ''
def parse(s):
    s=(s or '').strip()
    m=re.search(r'\[罪名\](.*?)(?:<eoa>|$)',s)
    if m: s=m.group(1).strip()
    s=re.sub(r'<eoa>.*','',s).strip()
    for sep in [';','；',',','，','、']:
        if sep in s: return {p.strip() for p in s.split(sep) if p.strip()}
    return {s} if s else set()
for idx in ['0002','0009','0015','0023','0024','0035','0048','0017','0020','0021','0043']:
    try:
        t=json.load(open(f'/workspace/runs/{tree}/LawBench/conversations/{idx}/sample-0.json'))
    except FileNotFoundError: continue
    ctx='\n'.join(txt(m) for m in t['messages'] if m['role']=='tool')
    pred=parse(t['prediction']); tgt=parse(t['target']); miss=tgt-pred
    print(f'{idx}: missing={sorted(miss)}')
    for c in sorted(miss):
        # count how many retrieved answers contain c
        answers=re.findall(r'\nA: (.*)', ctx)
        n=sum(1 for a in answers if c in a)
        print(f'    {c}: in {n} of {len(answers)} retrieved answers; occurrences in ctx={ctx.count(c)}')
