"""Classify every notice the current check would draw, by rule, over recorded first passes."""
import json,re,sys
sys.path.insert(0,'/workspace/harness/solver')
import answer_conventions as A

def parse_target(s):
    return set(A.split_items(A.MARKUP.sub('',s or '')))

def profile_for(task):
    # take the memory of the most recent run for that task
    import glob
    tree={'LawBench':'4383c6264deaf3410877e957b8f891f1f3da2936'}.get(task)
    mem=json.load(open(f'/workspace/runs/{tree}/{task}/memory.json'))
    return mem['answer_profile']

def classify(profile, answer, seen):
    """Return list of (rule, item, suggestion) for the current code."""
    out=[]
    inv=profile.get('items') or {}
    if not (profile.get('vocabulary_like') and inv): return out
    known={}
    for item,count in inv.items(): known.setdefault(str(item).lower(),(str(item),count))
    answers=A._answer_counts(profile)
    separator=A.joining_separator(answers)
    pieces=A.name_pieces(inv,answers,separator)
    segments=A.answer_segments(answer,separator)
    endings,carriers=A._ending_statistics(inv)
    parts=A.written_parts(answers)
    shortest=min((len(str(i)) for i in inv),default=0)
    for item in A.answer_items(answer):
        if item.lower() in known:
            if item not in pieces or item not in segments: continue
            line=A._longer_name_notice(item,known)
            if line: out.append(('longer_name',item,re.findall(r'"([^"]*)"',line)))
            continue
        variant=A._closest_known(item,known)
        if variant is None:
            line=A._ending_notice(item,endings,carriers,parts,known)
            if line: out.append(('ending',item,re.findall(r'"([^"]*)"',line)))
            elif item in segments:
                line=A._unwritten_ending_notice(item,endings,carriers,parts,shortest)
                if line: out.append(('unwritten_ending',item,re.findall(r'"([^"]*)"',line)))
        else:
            known_item,count=variant
            comps=A._compositions(known_item,answers,separator,seen)
            if comps: out.append(('composition',item,[c[0] for c in comps]))
            else: out.append(('variant',item,[known_item]))
    return out

rows=json.load(open('/tmp/evo11/first_passes.json'))
prof={t:profile_for(t) for t in ['LawBench']}
from collections import Counter
stats=Counter(); detail=Counter()
for r in rows:
    if r['task']!='LawBench': continue
    tgt=parse_target(r['target'])
    ok = (parse_target(r['first'])==tgt)
    lines=classify(prof['LawBench'], r['first'], r['shown'])
    if not lines:
        stats['no_notice']+=1
        if ok: stats['no_notice_correct']+=1
        continue
    stats['notice']+=1
    if ok: stats['NOTICE_ON_CORRECT']+=1
    for rule,item,sugg in lines:
        detail[(rule,'fire')]+=1
        sag=set(sugg)
        if any(s in tgt for s in sag): detail[(rule,'suggests_target_item')]+=1
        # does applying the suggestion replace item with something in target?
        alt=set(A.split_items(re.sub(r'[；;，,]','、',r['first'])))
        alt2=(alt-{item})|set(s for s in sag)
        if alt2==tgt: detail[(rule,'rewrite_lands_on_target')]+=1
for k,v in sorted(stats.items()): print(f'{k:24s} {v}')
print()
for k,v in sorted(detail.items()): print(f'{k[0]:18s} {k[1]:24s} {v}')
EOF
