"""Compare ranking functions by where the first useful example lands."""
import json,math,re,sys
from collections import Counter
sys.path.insert(0,'/workspace/harness/solver'); sys.path.insert(0,'/workspace')
import benchmark.data.loaders as L
import answer_conventions as A

def shingles(text,n):
    text=re.sub(r'\s+',' ',(text or '').lower())
    return Counter(text[i:i+n] for i in range(max(0,len(text)-n+1)))
def docfreq(counts):
    f=Counter()
    for c in counts: f.update(c.keys())
    return f
def weigh(count,freq,documents,k=1.0):
    return {s:v*math.log(1+(documents/freq[s] if freq[s] else 1e9)) for s,v in count.items()}
def weigh_plain(count,freq,documents):
    return {s:v*math.log(documents/(1+freq[s])) for s,v in count.items()}
def cos(a,b,nb):
    shared=a.keys()&b.keys()
    num=sum(a[s]*b[s] for s in shared)
    na=math.sqrt(sum(v*v for v in a.values()))
    return num/(na*nb) if na*nb else 0.0

def split_items(t):
    t=(t or '').strip()
    for sep in [';','；',',','，','、']:
        if sep in t: return [p.strip() for p in t.split(sep) if p.strip()]
    return [t] if t else []

def evaluate(task, n, weigher, use_raw=True):
    tr=L.load_mce_dataset(task,'train'); va=L.load_mce_dataset(task,'val')
    qs=[(e.get('raw_question') or e['input']) if use_raw else e['input'] for e in tr]
    counts=[shingles(q,n) for q in qs]; freq=docfreq(counts)
    vecs=[weigher(c,freq,len(qs)) for c in counts]
    norms=[math.sqrt(sum(v*v for v in vec.values())) for vec in vecs]
    ranks=[]
    for ex in va:
        q=(ex.get('raw_question') or ex['input']) if use_raw else ex['input']
        asked=weigher(shingles(q,n),freq,len(qs))
        ranked=sorted(range(len(tr)),key=lambda j:(-cos(asked,vecs[j],norms[j]),j))
        if task=='LawBench':
            tgt=set(split_items(ex['target']))
            good=lambda j: bool(set(split_items(tr[j]['target']))&tgt) or tr[j]['target']==ex['target']
        else:
            good=lambda j: tr[j]['target']==ex['target']
        r=next((i for i,j in enumerate(ranked) if good(j)),None)
        if r is not None: ranks.append(r)
    return len(ranks), (sum(ranks)/len(ranks) if ranks else 0), (sorted(ranks)[len(ranks)//2] if ranks else -1), sum(1 for r in ranks if r<5), sum(1 for r in ranks if r<10)

from collections import Counter
for task in ['LawBench','Symptom2Disease','USPTO']:
    print('==',task)
    for n in (1,2,3,4):
        for wname,w in (('idf+1',lambda c,f,d: weigh(c,f,d)),('plain',weigh_plain)):
            f,mean,med,t5,t10=evaluate(task,n,w)
            print(f'   n={n} {wname:6s} found {f}/50 mean {mean:6.1f} median {med:4d} top5 {t5:3d} top10 {t10:3d}')
